\begin{algorithm}[t]
  \small
  \caption{Iterative Group Relative Policy Optimization}
  \textbf{Input} initial policy model $\pi_{\theta_{\text{init}}}$; reward models $r_\varphi$; task prompts $\mathcal{D}$; 
  hyperparameters $\varepsilon$, $\beta$, $\mu$
